using System.IO;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Data;

namespace TrMarketplaceHubDesktop;

public static class OrderArchiveWindow
{
    public static void Show(Window? owner,OrdersStore store,Action changed)
    {
        var win=new Window{Title="Sipariş arşivi",Width=1050,Height=650,Owner=owner,WindowStartupLocation=owner is null?WindowStartupLocation.CenterScreen:WindowStartupLocation.CenterOwner};var root=new DockPanel{Margin=new Thickness(12)};win.Content=root;var status=new TextBlock{Margin=new Thickness(4),TextWrapping=TextWrapping.Wrap};DockPanel.SetDock(status,Dock.Bottom);root.Children.Add(status);var top=new WrapPanel();DockPanel.SetDock(top,Dock.Top);root.Children.Add(top);var grid=new DataGrid{AutoGenerateColumns=false,IsReadOnly=true,SelectionMode=DataGridSelectionMode.Single};root.Children.Add(grid);
        foreach(var tuple in new[]{("Pazaryeri","Marketplace",110d),("Mağaza","ShopId",100d),("Sipariş No","OrderId",150d),("Müşteri","CustomerName",190d),("Durum","StatusLabel",140d),("Toplam","TotalLabel",120d)})grid.Columns.Add(new DataGridTextColumn{Header=tuple.Item1,Binding=new Binding(tuple.Item2),Width=tuple.Item3});
        void Load(){grid.ItemsSource=store.ReadArchived();status.Text=$"{((IEnumerable<OrderSnapshot>)grid.ItemsSource).Count()} arşiv kaydı";}
        var restore=new Button{Content="Seçili siparişi geri yükle",Margin=new Thickness(3)};restore.Click+=(_,_)=>{try{if(grid.SelectedItem is not OrderSnapshot order)throw new InvalidOperationException("Önce arşiv kaydı seçin.");store.Restore(order.Marketplace,order.ShopId,order.OrderId);Load();changed();status.Text="Sipariş etkin listeye geri yüklendi.";}catch(Exception ex){status.Text=MarketplaceConnectionStore.Redact(ex.Message);}};top.Children.Add(restore);Load();win.ShowDialog();
    }
}

public static class TrendyolLiveActionsWindow
{
    public static void Show(Window? owner,OrderSnapshot order,string? directory,Action changed)
    {
        if(!order.Marketplace.Equals("Trendyol",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Bu ekran yalnız Trendyol siparişleri içindir.");var settings=TrendyolOrderWriteGuard.Resolve(directory,order.ShopId);var client=new TrendyolOrderActionClient(settings,null,directory is null?null:new TrendyolActionLedger(directory));
        var win=new Window{Title="Trendyol canlı iptal ve iade",Width=850,Height=650,Owner=owner,WindowStartupLocation=owner is null?WindowStartupLocation.CenterScreen:WindowStartupLocation.CenterOwner};var panel=new StackPanel{Margin=new Thickness(16)};win.Content=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};panel.Children.Add(new TextBlock{Text=$"Sipariş {order.OrderId} · Paket {order.Shipments.FirstOrDefault()?.Id}",FontSize=20,FontWeight=FontWeights.SemiBold});var status=new TextBlock{TextWrapping=TextWrapping.Wrap,Margin=new Thickness(3,10,3,10)};panel.Children.Add(status);
        panel.Children.Add(new TextBlock{Text="Tedarik edememe nedeni"});var reason=new ComboBox{ItemsSource=new[]{new KeyValuePair<int,string>(500,"Stok tükendi"),new(501,"Hatalı fiyat"),new(502,"Ürün hasarlı"),new(504,"Tedarik sorunu"),new(505,"Yanlış ürün bilgisi"),new(506,"Diğer")},DisplayMemberPath="Value",SelectedValuePath="Key",SelectedIndex=0};panel.Children.Add(reason);var confirmCancel=new CheckBox{Content="Seçili sipariş kalemlerinin Trendyol'da iptal edileceğini onaylıyorum.",Margin=new Thickness(3,12,3,5)};panel.Children.Add(confirmCancel);
        var cancel=new Button{Content="Tedarik edilemedi bildir",Padding=new Thickness(10,5,10,5),Margin=new Thickness(3)};cancel.Click+=async(_,_)=>{try{cancel.IsEnabled=false;if(!long.TryParse(order.Shipments.FirstOrDefault()?.Id,out var packageId))throw new InvalidOperationException("Geçerli Trendyol paket kimliği yok.");var lines=order.Items.Select(x=>new TrendyolUnsuppliedLine(x.MarketplaceLineId,x.Quantity)).ToList();await client.MarkUnsuppliedAsync(packageId,lines,(int)(reason.SelectedValue??500),confirmCancel.IsChecked==true);status.Text="Trendyol iptal bildirimi kabul edildi. Sipariş listesini yenileyin; kısmi iptalde paket kimliği değişebilir.";changed();}catch(Exception ex){status.Text=MarketplaceConnectionStore.Redact(ex.Message);}finally{cancel.IsEnabled=true;}};panel.Children.Add(cancel);
        panel.Children.Add(new Separator{Margin=new Thickness(0,18,0,10)});var claims=new DataGrid{AutoGenerateColumns=true,IsReadOnly=true,Height=250,SelectionMode=DataGridSelectionMode.Single};panel.Children.Add(claims);var load=new Button{Content="Son 30 gün iadelerini getir",Margin=new Thickness(3)};load.Click+=async(_,_)=>{try{load.IsEnabled=false;claims.ItemsSource=await client.GetClaimsAsync(DateTimeOffset.UtcNow.AddDays(-30),DateTimeOffset.UtcNow);status.Text="İade talepleri yenilendi.";}catch(Exception ex){status.Text=MarketplaceConnectionStore.Redact(ex.Message);}finally{load.IsEnabled=true;}};panel.Children.Add(load);var confirmReturn=new CheckBox{Content="Seçili iadenin Trendyol'da kabul edileceğini onaylıyorum.",Margin=new Thickness(3,8,3,3)};panel.Children.Add(confirmReturn);var approve=new Button{Content="Seçili iadeyi kabul et",Margin=new Thickness(3)};approve.Click+=async(_,_)=>{try{approve.IsEnabled=false;if(claims.SelectedItem is not TrendyolClaim claim)throw new InvalidOperationException("Önce iade talebi seçin.");if(!claim.Status.Equals("WaitingInAction",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Yalnız işlem bekleyen iade kabul edilebilir.");await client.ApproveClaimAsync(claim.ClaimId,claim.ClaimLineItemIds,confirmReturn.IsChecked==true);status.Text="İade kabulü Trendyol'a gönderildi.";}catch(Exception ex){status.Text=MarketplaceConnectionStore.Redact(ex.Message);}finally{approve.IsEnabled=true;}};panel.Children.Add(approve);
        var rejectReason=new TextBox{Margin=new Thickness(3),ToolTip="Trendyol iade ret nedeni ID"};panel.Children.Add(rejectReason);var rejectDescription=new TextBox{Margin=new Thickness(3),ToolTip="İade ret açıklaması (3-500 karakter)"};panel.Children.Add(rejectDescription);var confirmReject=new CheckBox{Content="Seçili iade için Trendyol'a ret/sorun bildirileceğini onaylıyorum.",Margin=new Thickness(3)};panel.Children.Add(confirmReject);var reject=new Button{Content="Seçili iadeyi reddet / sorun bildir",Margin=new Thickness(3)};reject.Click+=async(_,_)=>{try{reject.IsEnabled=false;if(claims.SelectedItem is not TrendyolClaim claim)throw new InvalidOperationException("Önce iade talebi seçin.");if(!claim.Status.Equals("WaitingInAction",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Yalnız işlem bekleyen iade için sorun bildirilebilir.");if(!long.TryParse(rejectReason.Text,out var reasonId))throw new InvalidOperationException("Trendyol ret nedeni ID girin.");await client.RejectClaimAsync(claim.ClaimId,claim.ClaimLineItemIds,reasonId,rejectDescription.Text,confirmReject.IsChecked==true);status.Text="İade ret/sorun bildirimi Trendyol'a gönderildi.";}catch(Exception ex){status.Text=MarketplaceConnectionStore.Redact(ex.Message);}finally{reject.IsEnabled=true;}};panel.Children.Add(reject);win.ShowDialog();
    }
}
